function [b] = field_eci_ecef(r, c, gh, nmax)
%FIELD_ECI_ECEF  The field in J2000 [T, as plain numbers] at an Earth-fixed position, its geodetic coordinates by geodetic5.
%   r: real[m][3] (passed in m)
%   c: real[1][3][3] (passed a plain number)
%   gh: real[1][195] (passed a plain number)
%   nmax: int (passed a whole number)
%   returns b: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    b = zeros(3, 1);
    [lat, lon, h] = asils.models.truthfield.geodetic5(r);
